const CloudSync={submitToCloud:async function(e,o){if("undefined"==typeof firebase||!firebase.apps.length)return console.warn("[STEMulus] Firebase not initialized. Skipping cloud sync."),!1;try{const n=firebase.firestore();return await n.collection(e).add({...o,timestamp:firebase.firestore.FieldValue.serverTimestamp(),domain:window.location.hostname}),console.log(`[STEMulus] Data synced to ${e} ☁️`),!0}catch(e){return console.error("[STEMulus] Cloud Sync Error:",e),!1}},listenToContent:function(e,o){if("undefined"!=typeof firebase&&firebase.apps.length)return firebase.firestore().collection(e).orderBy("timestamp","desc").onSnapshot(e=>{const n=e.docs.map(e=>({id:e.id,...e.data()}));o(n)})}};